<?php
namespace App\Policies;use App\Domain\Tenancy\TenantContext;use App\Models\{UnderwritingCase,User};final class UnderwritingCasePolicy{private function a(User$u):bool{return$u->memberships()->where(['tenant_id'=>app(TenantContext::class)->id(),'status'=>'ACTIVE'])->whereIn('role_code',['SYSTEM_ADMIN','PLATFORM_ADMIN','UNDERWRITER','UNDERWRITING_MANAGER','CARRIER_ADMIN'])->exists();}public function viewAny(User$u):bool{return$this->a($u);}public function view(User$u,UnderwritingCase$m):bool{return$this->a($u)&&$m->tenant_id===app(TenantContext::class)->id();}public function create(User$u):bool{return false;}public function update(User$u,UnderwritingCase$m):bool{return$this->view($u,$m)&&$m->status!=='DECIDED';}public function delete(User$u,UnderwritingCase$m):bool{return false;}}
